def mixed(i: int, bases: list[str]) -> tuple[str, int]:
    return bases[i % len(bases)], i // len(bases)

def make_row(fact, variant):
    domain, subject, focus, claim, note, source = fact
    x = variant
    qa, x = mixed(x, Q_A)
    qb, x = mixed(x, Q_B)
    qc, x = mixed(x, Q_C)
    qd, x = mixed(x, Q_D)
    aa, x = mixed(x, A_A)
    ab, x = mixed(x, A_B)
    ac, x = mixed(x, A_C)
    ad, x = mixed(x, A_D)
    question = f"{qa} {subject} {focus}, {qb} {qc} {qd}"
    answer = f"{aa} {claim} {ab} {note} {ac} {ad}"
    return {"question": question, "answer": answer, "domain": domain, "source": source, "fact_id": f"F{FACTS.index(fact)+1:03d}"}

def main():
    p = argparse.ArgumentParser()
    p.add_argument("--count", type=int, default=500_000)
    p.add_argument("--output", type=Path, default=Path("factual_pedantic_500k.jsonl.gz"))
    args = p.parse_args()
    capacity = len(FACTS) * 10_000
    if not 1 <= args.count <= capacity:
        raise SystemExit(f"--count must be between 1 and {capacity}")
    seen_q, seen_a = set(), set()
    digest = hashlib.sha256()
    per_fact = (args.count + len(FACTS) - 1) // len(FACTS)
    with gzip.open(args.output, "wt", encoding="utf-8", newline="\n", compresslevel=9) as out:
        written = 0
        for fact in FACTS:
            for variant in range(min(10_000, args.count-written)):
                row = make_row(fact, variant)
                if row["question"] in seen_q or row["answer"] in seen_a:
                    raise RuntimeError(f"duplicate at row {written}")
                seen_q.add(row["question"]); seen_a.add(row["answer"])
                line = json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n"
                out.write(line); digest.update(line.encode("utf-8")); written += 1
                if written >= args.count: break
            if written >= args.count: break
    manifest = {
        "dataset": args.output.name, "rows": written,
        "unique_questions": len(seen_q), "unique_answers": len(seen_a),
        "fact_records": len(FACTS), "domains": sorted({f[0] for f in FACTS}),
        "format": "JSONL gzip", "encoding": "UTF-8",
        "sha256_uncompressed_jsonl": digest.hexdigest(),
        "generation": "deterministic paraphrase combinations over a reviewed fact bank",
        "source_policy": "Every row includes a source URL; inspect source quality before training.",
        "synthetic_warning": "Surface forms are synthetic. Underlying claims are curated; not a substitute for source-level fact checking."
    }
    args.output.with_suffix(args.output.suffix + ".manifest.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2)+"\n", encoding="utf-8")
    print(json.dumps(manifest, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    main()
